await game.snippet("flecha-arco");

game.herramientas.define('ballesta', {
  dibujo: 'asset:assets/ballesta.vox.json',
  nombre: '🏹 ballesta',
  mira: '⊙',
  ayuda: 'ballesta · clic izq: disparar flecha · clic dcho: estocada / impulso',
  pos: [0.85, -0.55, 0],
  rot: [-6, -80, -18],
  escala: 0.75,
  gesto: { dur: 0.40, windupP: 0.12, strikeP: 0.042, windupRot: -0.55, chopRot: 0.60, lift: 0.016, drop: 0.05, reach: -0.0155 },
  gestoBotones: [0, 2],
  anima(e){
    const quieta = (e.disparo < 0) ? 1 : 0;
    return {
      pos: [0, Math.sin(e.t * 1.4) * 0.012 * quieta, 0],
      rot: [0, 0, Math.sin(e.t * 0.9) * 2.5 * quieta]
    };
  },
  izquierdo(c){
    game.ballesta.disparos++;
    game.dispararFlecha({ velocidad: 64, gravedad: 9.8 });
  },
  derecho(c){
    game.dispararFlecha({ velocidad: 45, gravedad: 7.0 });
    const cp = Math.cos(mc.pitch), f = game.ballesta.impulso;
    mc.vel[0] = -Math.sin(mc.yaw) * cp * f;
    mc.vel[2] = -Math.cos(mc.yaw) * cp * f;
    mc.vel[1] = Math.max(mc.vel[1], game.ballesta.despegue * Math.sqrt(mc.scale));
    mc.onGround = false;
    game.ballesta.estocadas++;
    toast('⚔️ ¡Impulso de ballesta! #' + game.ballesta.estocadas);
  }
});

game.ballesta = { disparos: 0, estocadas: 0, impulso: 10, despegue: 3.2 };
game.playerTool = 'ballesta';
toast('🏹 Ballesta equipada · Clic izq: disparar · Clic dcho: disparo con impulso');
